import pty, os, subprocess, select, time

def run_case(stdout_tty, stderr_tty, term=None):
    master_out, slave_out = (None, None)
    master_err, slave_err = (None, None)
    env = {k:v for k,v in os.environ.items() if k!="RICHGO_FORCE_COLOR"}
    if term is not None:
        env["TERM"] = term
    else:
        env.pop("TERM", None)
    # Note: keep TERM? Let's test both
    stdout_arg = subprocess.PIPE
    stderr_arg = subprocess.PIPE
    if stdout_tty:
        master_out, slave_out = pty.openpty()
        stdout_arg = slave_out
    if stderr_tty:
        master_err, slave_err = pty.openpty()
        stderr_arg = slave_err
    p = subprocess.Popen(["./executable","testfilter"], stdin=subprocess.PIPE, stdout=stdout_arg, stderr=stderr_arg, text=False, env=env)
    if stdout_tty:
        os.close(slave_out)
    if stderr_tty:
        os.close(slave_err)
    # write stdin
    p.stdin.write(b"=== RUN   TestFoo\n")
    p.stdin.close()
    out_data = b""
    err_data = b""
    # collect
    # if pipe, read via communicate? Need to handle mixed
    # We'll read from masters and pipes
    import threading
    def read_pipe(pipe, container):
        try:
            d = pipe.read()
            container.append(d)
        except Exception as e:
            container.append(f"ERR:{e}".encode())
    out_pipe_data = []
    err_pipe_data = []
    threads=[]
    if not stdout_tty:
        import threading
        t = threading.Thread(target=lambda: out_pipe_data.append(p.stdout.read()))
        t.start(); threads.append(t)
    if not stderr_tty:
        t = threading.Thread(target=lambda: err_pipe_data.append(p.stderr.read()))
        t.start(); threads.append(t)
    # read from ptys
    masters = []
    if stdout_tty: masters.append(("out", master_out))
    if stderr_tty: masters.append(("err", master_err))
    # poll
    collected = {"out": b"", "err": b""}
    # Use select loop until process exits
    import time
    start=time.time()
    fds = [m for _,m in masters]
    # set nonblocking?
    import fcntl, os
    for _,m in masters:
        flags = fcntl.fcntl(m, fcntl.F_GETFL)
        fcntl.fcntl(m, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    while p.poll() is None and time.time()-start < 3:
        try:
            r,_,_ = select.select(fds, [], [], 0.2)
            for fd in r:
                try:
                    d = os.read(fd, 4096)
                    if d:
                        for name, m in masters:
                            if m==fd:
                                collected[name]+=d
                except OSError:
                    pass
        except: break
    # drain remaining
    time.sleep(0.2)
    for name, m in masters:
        try:
            while True:
                d = os.read(m, 4096)
                if not d: break
                collected[name]+=d
        except: pass
        os.close(m)
    for t in threads:
        t.join(timeout=2)
    p.wait(timeout=2)
    if not stdout_tty:
        collected["out"] = out_pipe_data[0] if out_pipe_data else b""
        # p.stdout already read
    else:
        # already collected
        pass
    if not stderr_tty:
        collected["err"] = err_pipe_data[0] if err_pipe_data else b""
    print(f"stdout_tty={stdout_tty} stderr_tty={stderr_tty} TERM={repr(term)} -> OUT:{repr(collected['out'])} ERR:{repr(collected['err'])} rc:{p.returncode}")

for st in [False, True]:
    for et in [False, True]:
        for term in ["xterm", None, "dumb"]:
            run_case(st, et, term)
