        t=threading.Thread(target=lambda: out_pipe_data.append(p.stdout.read()))
        t.start(); threads.append(t)
    if not stderr_tty:
        t=threading.Thread(target=lambda: err_pipe_data.append(p.stderr.read()))
        t.start(); threads.append(t)
    masters=[]
    if stdout_tty: masters.append(("out", master_out))
