		for _, ch := range s[2:] {
			if !((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')) {
				return 0, false
			}
		}
		n, _ := strconv.ParseInt(s[2:], 16, 0)
		return int(n), true
	}
	// Decimal: 1-3 digits, value 0-255, all digits, no sign, no spaces (already checked)
	if len(s) < 1 || len(s) > 3 {
		return 0, false
	}
	for _, ch := range s {
		if ch < '0' || ch > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 || n > 255 {
		return 0, false
	}
	return n, true
}

// StyleConfig for YAML with pointers for merging
type StyleConfig struct {
	Hide       *bool  `yaml:"hide"`
	Bold       *bool  `yaml:"bold"`
	Faint      *bool  `yaml:"faint"`
	Italic     *bool  `yaml:"italic"`
