		return 0, 0, 0, false
	}
	// parts[1]: leading spaces allowed, but no tabs, no trailing spaces? Actually trailing spaces before comma would be in parts[1]? No, parts[1] is between first comma and second comma. Trailing spaces before second comma would be at end of parts[1]. So parts[1] must not end with space? Wait, space before comma is invalid (as in "255 ,0,0" invalid). That space would be at end of parts[0]? No, "255 ,0,0" inside is "255 ,0,0", split by "," gives ["255 ", "0", "0"]. parts[0] is "255 " with trailing space, which we already reject (since parts[0] contains space). Good.
	// For parts[1], leading spaces allowed (after first comma), trailing spaces before second comma invalid. So parts[1] must be " *" + number with no trailing spaces. How to check? Trim leading spaces, then ensure no spaces remain.
	// Similarly parts[2]: leading spaces allowed, no trailing (before ")").
	// Also need to ensure no tabs anywhere? Tabs invalid everywhere (as in "255,\t0,0" invalid). So check for tabs in any part -> invalid.
	for _, p := range parts {
		if strings.Contains(p, "\t") {
			return 0, 0, 0, false
		}
	}
	// Validate parts[0]
	r, ok := parseRGBComponent(parts[0])
	if !ok {
		return 0, 0, 0, false
	}
	// Validate parts[1]: trim leading spaces (only spaces, not tabs, but tabs already rejected)
	p1Trimmed := strings.TrimLeft(parts[1], " ")
	// After trimming leading spaces, must have no spaces left (no trailing, no internal)
	if strings.Contains(p1Trimmed, " ") {
		return 0, 0, 0, false
	}
	if p1Trimmed == "" {
		return 0, 0, 0, false
	}
	g, ok := parseRGBComponent(p1Trimmed)
	if !ok {
		return 0, 0, 0, false
	}
	// Validate parts[2]: same
	p2Trimmed := strings.TrimLeft(parts[2], " ")
	if strings.Contains(p2Trimmed, " ") {
		return 0, 0, 0, false
	}
	if p2Trimmed == "" {
		return 0, 0, 0, false
	}
	b, ok := parseRGBComponent(p2Trimmed)
	if !ok {
		return 0, 0, 0, false
	}
	return r, g, b, true
}

func parseRGBComponent(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	// Check hex: 0x or 0X + exactly 2 hex digits
	if len(s) >= 3 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X') {
		if len(s) != 4 {
			return 0, false
		}
		for _, ch := range s[2:] {
			if !((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')) {
				return 0, false
			}
		}
		n, _ := strconv.ParseInt(s[2:], 16, 0)
		return int(n), true
	}
	// Decimal: 1-3 digits, value 0-255, all digits, no sign, no spaces (already checked)
	if len(s) < 1 || len(s) > 3 {
		return 0, false
	}
	for _, ch := range s {
		if ch < '0' || ch > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 || n > 255 {
		return 0, false
	}
	return n, true
}

