func newEmptyStyleConfig() *StyleConfig {
	return &StyleConfig{}
}

func mergeStyle(dst, src *StyleConfig) *StyleConfig {
	if src == nil {
		return dst
	}
	if dst == nil {
		dst = newEmptyStyleConfig()
	}
	if src.Hide != nil {
		dst.Hide = src.Hide
	}
	if src.Bold != nil {
		dst.Bold = src.Bold
	}
	if src.Faint != nil {
		dst.Faint = src.Faint
	}
	if src.Italic != nil {
		dst.Italic = src.Italic
	}
	if src.Underline != nil {
		dst.Underline = src.Underline
	}
	if src.BlinkSlow != nil {
		dst.BlinkSlow = src.BlinkSlow
	}
	if src.BlinkRapid != nil {
		dst.BlinkRapid = src.BlinkRapid
	}
	if src.Inverse != nil {
		dst.Inverse = src.Inverse
	}
	if src.Conceal != nil {
		dst.Conceal = src.Conceal
	}
	if src.CrossOut != nil {
		dst.CrossOut = src.CrossOut
	}
	if src.Frame != nil {
		dst.Frame = src.Frame
	}
	if src.Encircle != nil {
		dst.Encircle = src.Encircle
	}
	if src.Overline != nil {
		dst.Overline = src.Overline
	}
	if src.Foreground != nil {
		dst.Foreground = src.Foreground
	}
	if src.Background != nil {
		dst.Background = src.Background
	}
	return dst
}

func loadConfig() *FinalConfig {
	merged := &MergedConfig{}
	// Determine paths
	var paths []string
	cwd, err := os.Getwd()
	if err == nil && cwd != "" {
		paths = append(paths,
			filepath.Join(cwd, ".richstyle"),
			filepath.Join(cwd, ".richstyle.yaml"),
			filepath.Join(cwd, ".richstyle.yml"),
		)
	} else if err != nil {
		// If Getwd fails, skip CWD? No error logged? Original probably skips silently. Good.
	}
	if os.Getenv("RICHGO_LOCAL") != "1" {
		// GOPATH
		gopath := os.Getenv("GOPATH")
		if gopath == "" {
			home := os.Getenv("HOME")
			if home != "" {
				gopath = filepath.Join(home, "go")
			}
		}
		if gopath != "" {
			paths = append(paths,
				filepath.Join(gopath, ".richstyle"),
				filepath.Join(gopath, ".richstyle.yaml"),
				filepath.Join(gopath, ".richstyle.yml"),
			)
		}
		// GOROOT
		goroot := os.Getenv("GOROOT")
		if goroot == "" {
			goroot = runtime.GOROOT()
		}
		if goroot != "" {
			paths = append(paths,
				filepath.Join(goroot, ".richstyle"),
				filepath.Join(goroot, ".richstyle.yaml"),
				filepath.Join(goroot, ".richstyle.yml"),
			)
		}
		// HOME
		home := os.Getenv("HOME")
		if home != "" {
			paths = append(paths,
				filepath.Join(home, ".richstyle"),
				filepath.Join(home, ".richstyle.yaml"),
				filepath.Join(home, ".richstyle.yml"),
			)
		}
	}
	for _, p := range paths {
		data, err := os.ReadFile(p)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			// Log read error
			log.Printf("error reading from %s :  %v", p, err)
			continue
		}
		var fc FileConfig
		if err := yaml.Unmarshal(data, &fc); err != nil {
			log.Printf("error unmarshaling yaml from %s :  %v", p, err)
			continue
		}
		// Merge
		if fc.LabelType != nil {
			merged.LabelType = fc.LabelType
		}
		merged.BuildStyle = mergeStyle(merged.BuildStyle, fc.BuildStyle)
		merged.StartStyle = mergeStyle(merged.StartStyle, fc.StartStyle)
		merged.PassStyle = mergeStyle(merged.PassStyle, fc.PassStyle)
		merged.FailStyle = mergeStyle(merged.FailStyle, fc.FailStyle)
		merged.SkipStyle = mergeStyle(merged.SkipStyle, fc.SkipStyle)
		merged.FileStyle = mergeStyle(merged.FileStyle, fc.FileStyle)
		merged.LineStyle = mergeStyle(merged.LineStyle, fc.LineStyle)
		merged.PassPackageStyle = mergeStyle(merged.PassPackageStyle, fc.PassPackageStyle)
		merged.FailPackageStyle = mergeStyle(merged.FailPackageStyle, fc.FailPackageStyle)
		if fc.CoverThreshold != nil {
			merged.CoverThreshold = fc.CoverThreshold
		}
		merged.CoveredStyle = mergeStyle(merged.CoveredStyle, fc.CoveredStyle)
		merged.UncoveredStyle = mergeStyle(merged.UncoveredStyle, fc.UncoveredStyle)
		if len(fc.Removals) > 0 {
			// Prepend new removals to front (later files first)
			merged.Removals = append(fc.Removals, merged.Removals...)
		}
		// Note: if fc.Removals is nil/empty (missing or [] or null), append nothing (preserve)
		if fc.LeaveTestPrefix != nil {
			merged.LeaveTestPrefix = fc.LeaveTestPrefix
		}
	}
	return resolveConfig(merged)
}

func boolOrDefault(p *bool, def bool) bool {
	if p == nil {
		return def
	}
	return *p
}

func colorOrDefault(p *Color, defName string) *Color {
	if p == nil {
		// Use default
		if defName == "" {
			return nil
		}
		c := &Color{isNamed: true, name: defName, raw: defName}
		return c
	}
	if p.isEmpty {
		return nil
	}
	return p
}

func resolveStyle(sc *StyleConfig, defHide, defBold bool, defFG string) Style {
	var s Style
	if sc == nil {
		sc = &StyleConfig{}
	}
	s.Hide = boolOrDefault(sc.Hide, defHide)
	s.Bold = boolOrDefault(sc.Bold, defBold)
	s.Faint = boolOrDefault(sc.Faint, false)
	s.Italic = boolOrDefault(sc.Italic, false)
	s.Underline = boolOrDefault(sc.Underline, false)
	s.BlinkSlow = boolOrDefault(sc.BlinkSlow, false)
	s.BlinkRapid = boolOrDefault(sc.BlinkRapid, false)
	s.Inverse = boolOrDefault(sc.Inverse, false)
	s.Conceal = boolOrDefault(sc.Conceal, false)
	s.CrossOut = boolOrDefault(sc.CrossOut, false)
	s.Frame = boolOrDefault(sc.Frame, false)
	s.Encircle = boolOrDefault(sc.Encircle, false)
	s.Overline = boolOrDefault(sc.Overline, false)
	// Foreground
	if sc.Foreground == nil {
		if defFG == "" {
			s.Foreground = nil
		} else {
			s.Foreground = &Color{isNamed: true, name: defFG, raw: defFG}
		}
	} else {
		if sc.Foreground.isEmpty {
			s.Foreground = nil
		} else {
			s.Foreground = sc.Foreground
		}
	}
	// Background (default none)
	if sc.Background == nil {
		s.Background = nil
	} else {
		if sc.Background.isEmpty {
			s.Background = nil
		} else {
			s.Background = sc.Background
		}
	}
	return s
}

func resolveConfig(m *MergedConfig) *FinalConfig {
	fc := &FinalConfig{}
	// LabelType
	if m.LabelType == nil {
		fc.LabelType = "long"
	} else {
		v := *m.LabelType
		if v == "long" || v == "short" || v == "none" {
			fc.LabelType = v
		} else {
			fc.LabelType = "none"
		}
	}
	// Styles with defaults per README
	fc.Build = resolveStyle(m.BuildStyle, false, true, "yellow")
	fc.Start = resolveStyle(m.StartStyle, false, false, "lightBlack")
	fc.Pass = resolveStyle(m.PassStyle, false, false, "green")
	fc.Fail = resolveStyle(m.FailStyle, false, true, "red")
	fc.Skip = resolveStyle(m.SkipStyle, false, false, "lightBlack")
	fc.File = resolveStyle(m.FileStyle, false, false, "cyan")
	fc.Line = resolveStyle(m.LineStyle, false, false, "magenta")
	fc.PassPackage = resolveStyle(m.PassPackageStyle, true, false, "green")
	fc.FailPackage = resolveStyle(m.FailPackageStyle, true, true, "red")
	if m.CoverThreshold == nil {
		fc.CoverThreshold = 50
	} else {
		fc.CoverThreshold = *m.CoverThreshold
	}
	fc.Covered = resolveStyle(m.CoveredStyle, false, false, "green")
	fc.Uncovered = resolveStyle(m.UncoveredStyle, false, true, "yellow")
	fc.Removals = m.Removals
	if m.LeaveTestPrefix == nil {
		fc.LeaveTestPrefix = false
	} else {
		fc.LeaveTestPrefix = *m.LeaveTestPrefix
	}
	return fc
}

// ANSI generation
func (s Style) prefixCodes(isBackground bool) []string {
	// Returns list of codes as strings like "31", "1", etc, in order: background, foreground, then attributes
	var codes []string
	if s.Background != nil {
		if code := s.Background.ansiCode(true); code != "" {
			codes = append(codes, code)
		}
	}
	if s.Foreground != nil {
		if code := s.Foreground.ansiCode(false); code != "" {
			codes = append(codes, code)
		}
	}
	if s.Bold {
		codes = append(codes, "1")
	}
	if s.Faint {
		codes = append(codes, "2")
	}
	if s.Italic {
		codes = append(codes, "3")
	}
	if s.Underline {
		codes = append(codes, "4")
	}
	if s.BlinkSlow {
		codes = append(codes, "5")
	}
	if s.BlinkRapid {
		codes = append(codes, "6")
	}
	if s.Inverse {
		codes = append(codes, "7")
	}
	if s.Conceal {
		codes = append(codes, "8")
	}
	if s.CrossOut {
		codes = append(codes, "9")
	}
	if s.Frame {
		codes = append(codes, "51")
	}
	if s.Encircle {
		codes = append(codes, "52")
	}
	if s.Overline {
		codes = append(codes, "53")
	}
	return codes
}

func (s Style) startSeq() string {
	codes := s.prefixCodes(false)
	if len(codes) == 0 {
		return ""
	}
	var sb strings.Builder
	for _, c := range codes {
		sb.WriteString("\x1b[" + c + "m")
	}
	return sb.String()
}

