actions.command:
cat > /workspace/filter.go <<'EOF'
package main

import (
	"bufio"
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

var fileRe = regexp.MustCompile(`([A-Za-z0-9_\-\./\\]+\.go)(:\d+(?::\d+)?)`)

func isPassStandalone(line string) bool {
	if !strings.HasPrefix(line, "PASS") {
		return false
	}
	rest := line[4:]
	for _, ch := range rest {
		if ch != ' ' && ch != '\t' {
			return false
		}
	}
	return true
}

func isFailStandalone(line string) bool {
	if !strings.HasPrefix(line, "FAIL") {
		return false
	}
	rest := line[4:]
	for _, ch := range rest {
		if ch != ' ' && ch != '\t' {
			return false
		}
	}
	return true
}

var okRe = regexp.MustCompile(`^ok\s+(\S+)\s+(\(cached\)|(?:\d+(?:\.\d*)?|\.\d+)s)(?:\s+coverage:\s+(\d+\.\d+% of statements))?(?:\s+\[(no test files|no tests to run)\])?\s*$`)

func parseOk(line string) (pkg, coverage string, ok bool) {
	m := okRe.FindStringSubmatch(line)
	if m == nil {
		return "", "", false
	}
	pkg = m[1]
	coverage = ""
	if m[3] != "" {
		coverage = "coverage: " + m[3]
	}
	return pkg, coverage, true
}

var failPkgRe = regexp.MustCompile(`^FAIL\s+\S+\s+(?:(?:\d+(?:\.\d*)?|\.\d+)s|\[build failed\])\s*$`)

func isFailPackage(line string) bool {
	return failPkgRe.MatchString(line)
}

var skipPkgRe = regexp.MustCompile(`^\?\s+\S+\s+\[(no test files|no tests to run)\]$`)

func isSkipPackage(line string) bool {
	return skipPkgRe.MatchString(line)
}

var coverRe = regexp.MustCompile(`^coverage: (\d+\.\d)% of statements$`)

func parseCoverage(line string) (pctStr string, pct float64, ok bool) {
	m := coverRe.FindStringSubmatch(line)
	if m == nil {
		return "", 0, false
	}
	pctStr = m[1] + "%"
	f, err := strconv.ParseFloat(m[1], 64)
	if err != nil {
		return "", 0, false
	}
	return pctStr, f, true
}

func parseBuild(line string) (content string, ok bool, isSingle bool) {
	if !strings.HasPrefix(line, "#") {
		return "", false, false
	}
	parts := strings.Split(line, " ")
	if len(parts) == 2 {
		if parts[0] != "#" {
			return "", false, false
		}
		return parts[1], true, true
	} else if len(parts) == 3 {
		if parts[0] != "#" {
			return "", false, false
		}
		pkg := parts[1]
		bracket := parts[2]
		if pkg == "" {
			return "", false, false
		}
		if len(bracket) < 2 || bracket[0] != '[' || bracket[len(bracket)-1] != ']' {
			return "", false, false
		}
		return pkg + " " + bracket, true, false
	}
	return "", false, false
}

func parseRun(line string) (name string, slashes int, ok bool) {
	const prefix = "=== RUN   "
	if !strings.HasPrefix(line, prefix) {
		return "", 0, false
	}
	rest := line[len(prefix):]
	if !strings.HasPrefix(rest, "Test") {
		return "", 0, false
	}
	slashes = strings.Count(rest, "/")
	return rest, slashes, true
}

func parseTestResult(line string) (label, name string, slashes int, ok bool, fallback bool) {
	i := 0
	for i < len(line) && (line[i] == ' ' || line[i] == '\t') {
		i++
	}
	leading := line[:i]
	rest := line[i:]
	var prefix string
	if strings.HasPrefix(rest, "--- PASS: ") {
		label = "PASS"
		prefix = "--- PASS: "
	} else if strings.HasPrefix(rest, "--- FAIL: ") {
		label = "FAIL"
		prefix = "--- FAIL: "
	} else if strings.HasPrefix(rest, "--- SKIP: ") {
		label = "SKIP"
		prefix = "--- SKIP: "
	} else {
		return "", "", 0, false, false
	}
	afterPrefix := rest[len(prefix):]
	if !strings.HasPrefix(afterPrefix, "Test") {
		return "", "", 0, false, false
	}
	if strings.Contains(leading, "\t") {
		trimmed := strings.TrimLeft(line, " ")
		slashes = strings.Count(line, "/")
		return label, trimmed, slashes, true, true
	}
	slashes = strings.Count(afterPrefix, "/")
	return label, afterPrefix, slashes, true, false
}

type filterState struct {
	current Style
	hasCurrent bool
}

func labelFor(styleName, labelType string) string {
	if labelType == "none" {
		return ""
	}
	if labelType == "short" {
		switch styleName {
		case "BUILD":
			return "!!"
		case "START":
			return ">"
		case "PASS":
			return "o"
		case "FAIL":
			return "x"
		case "SKIP":
			return "-"
		case "COVER":
			return "%"
		case "":
			return ""
		}
		return ""
	}
	return styleName
}

func formatPrefix(label, labelType string) string {
	if labelType == "none" {
		return ""
	}
	if labelType == "short" {
		return fmt.Sprintf("%-2s ", label)
	}
	return fmt.Sprintf("%-5s| ", label)
}

func applyRemovals(s string, res []*regexp.Regexp) string {
	for _, re := range res {
		s = re.ReplaceAllString(s, "")
	}
	return s
}

func highlightFiles(content string, fileStyle, lineStyle Style) string {
	return fileRe.ReplaceAllStringFunc(content, func(m string) string {
		sub := fileRe.FindStringSubmatch(m)
		if sub == nil {
			return m
		}
		filePart := sub[1]
		linePart := sub[2]
		var sb strings.Builder
		if !fileStyle.Hide {
			fs := fileStyle.startSeq()
			if fs != "" {
				sb.WriteString(fs)
				sb.WriteString(filePart)
				sb.WriteString("\x1b[0m")
			} else {
				sb.WriteString(filePart)
			}
		}
		if !lineStyle.Hide {
			ls := lineStyle.startSeq()
			if ls != "" {
				sb.WriteString(ls)
				sb.WriteString(linePart)
				sb.WriteString("\x1b[0m")
			} else {
				sb.WriteString(linePart)
			}
		}
		return sb.String()
	})
}

func filterStreamColor(reader *bufio.Reader, writer *bufio.Writer, config *FinalConfig, removals []*regexp.Regexp) {
	state := &filterState{hasCurrent: false}
	for {
		lineWithNL, err := reader.ReadString('\n')
		var line string
		if err == nil {
			line = strings.TrimSuffix(lineWithNL, "\n")
			line = strings.TrimSuffix(line, "\r")
		} else {
			if lineWithNL == "" {
				break
			}
			line = strings.TrimSuffix(lineWithNL, "\r")
			processLineColor(line, writer, config, removals, state)
			writer.Flush()
			break
		}
		processLineColor(line, writer, config, removals, state)
		writer.Flush()
		if err != nil {
			break
		}
	}
}

