	start := style.startSeq()
	end := ""
	if start != "" {
		end = "\x1b[0m"
	}
	coloredWithNL := start + formattedWithoutNL + end + "\n"
	after := applyRemovals(coloredWithNL, removals)
	if after == "" || after == "\n" {
		return
	}
	writer.WriteString(after)
}

