func isTerminal(fd uintptr) bool {
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}

func isColorEnabled() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") != "" {
		return true
	}
	return isTerminal(os.Stderr.Fd())
}

func main() {
	if len(os.Args) < 2 {
		delegateToGo(os.Args[1:])
		return
	}
	switch os.Args[1] {
	case "testfilter":
		runTestfilter()
	case "test":
		runTest(os.Args[1:])
	default:
		delegateToGo(os.Args[1:])
	}
}

func delegateToGo(args []string) {
	cmd := exec.Command("go", args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		panic(err)
	}
}

func compileRemovals(list []string) []*regexp.Regexp {
	var res []*regexp.Regexp
	for _, s := range list {
		res = append(res, regexp.MustCompile(s))
	}
	return res
}

func runTestfilter() {
